const DEVICE = {
    identifiers: ['maratui_esp32'],
    name: 'Lelit Mara',
    model: 'MaraTUI',
    manufacturer: 'Lelit'
};

function sensor(id, name, extra) {
    return {
        topic: `homeassistant/sensor/maratui_${id}/config`,
        payload: JSON.stringify(Object.assign({
            name: name,
            unique_id: `maratui_${id}`,
            state_topic: `homeassistant/sensor/maratui_${id}/state`,
            device: DEVICE
        }, extra)),
        qos: 1,
        retain: true
    };
}

function binary(id, name, extra) {
    return {
        topic: `homeassistant/binary_sensor/maratui_${id}/config`,
        payload: JSON.stringify(Object.assign({
            name: name,
            unique_id: `maratui_${id}`,
            state_topic: `homeassistant/binary_sensor/maratui_${id}/state`,
            payload_on: 'ON',
            payload_off: 'OFF',
            device: DEVICE
        }, extra)),
        qos: 1,
        retain: true
    };
}

const msgs = [
    sensor('mode', 'Mode', { icon: 'mdi:coffee-maker' }),
    sensor('firmware', 'Firmware Version', { icon: 'mdi:chip', entity_category: 'diagnostic' }),
    sensor('boiler_now', 'Boiler Temperature', {
        unit_of_measurement: '\u00b0C',
        device_class: 'temperature',
        state_class: 'measurement'
    }),
    sensor('boiler_target', 'Boiler Target', {
        unit_of_measurement: '\u00b0C',
        device_class: 'temperature',
        state_class: 'measurement'
    }),
    sensor('hx_now', 'HX Temperature', {
        unit_of_measurement: '\u00b0C',
        device_class: 'temperature',
        state_class: 'measurement'
    }),
    sensor('last_extraction_duration', 'Last Extraction Duration', {
        unit_of_measurement: 's',
        icon: 'mdi:coffee',
        state_class: 'measurement'
    }),
    sensor('extraction_timer', 'Extraction Timer', {
        unit_of_measurement: 's',
        icon: 'mdi:timer-play',
        state_class: 'measurement',
        force_update: true
    }),
    sensor('time_since_last_shot', 'Time Since Last Shot', {
        unit_of_measurement: 'min',
        icon: 'mdi:clock-outline',
        state_class: 'measurement'
    }),
    binary('heating', 'Heating', { device_class: 'heat' }),
    binary('pump', 'Pump Active', { icon: 'mdi:pump' }),
    binary('water_low', 'Water Level Low', { device_class: 'problem' })
];

return [msgs];

const d = msg.payload;
if (!d) return null;

const prev = context.get('prev') || {};
const now = Date.now();

// Live extraction timer — count seconds while pump_on
let extractionSecs = 0;
if (d.pump_on) {
    if (!prev.pump_on) {
        context.set('pump_start', now);
    }
    const start = context.get('pump_start') || now;
    extractionSecs = Math.floor((now - start) / 1000);
} else {
    context.set('pump_start', null);
}

// Time since last shot in minutes (updated from fn_events via flow context)
const lastShotEnd = flow.get('last_shot_end');
let timeSinceShotMin = null;
if (lastShotEnd && !d.pump_on) {
    timeSinceShotMin = Math.round((now - lastShotEnd) / 60000);
}

context.set('prev', d);

function s(id, val) {
    if (val === null || val === undefined) return null;
    return {
        topic: `homeassistant/sensor/maratui_${id}/state`,
        payload: String(val),
        qos: 0,
        retain: false
    };
}

function b(id, val) {
    return {
        topic: `homeassistant/binary_sensor/maratui_${id}/state`,
        payload: val ? 'ON' : 'OFF',
        qos: 0,
        retain: false
    };
}

const msgs = [
    s('mode', d.mode),
    s('firmware', d.sw),
    s('boiler_now', d.boiler_now_c),
    s('boiler_target', d.boiler_target_c),
    s('hx_now', d.hx_now_c),
    d.pump_on ? s('extraction_timer', extractionSecs) : null,
    timeSinceShotMin !== null ? s('time_since_last_shot', timeSinceShotMin) : null,
    b('heating', d.heating_on),
    b('pump', d.pump_on),
    b('water_low', d.no_water_code !== null && d.no_water_code !== undefined)
].filter(Boolean);

return [msgs];

const e = msg.payload;
if (!e) return null;

const msgs = [];

if (e.type === 'shot_ended') {
    flow.set('last_shot_end', Date.now());

    if (e.duration !== undefined) {
        msgs.push({
            topic: 'homeassistant/sensor/maratui_last_extraction_duration/state',
            payload: String(e.duration),
            qos: 1,
            retain: true
        });
        msgs.push({
            topic: 'homeassistant/sensor/maratui_extraction_timer/state',
            payload: String(e.duration),
            qos: 1,
            retain: true
        });
    }
    msgs.push({
        topic: 'homeassistant/sensor/maratui_time_since_last_shot/state',
        payload: '0',
        qos: 0,
        retain: false
    });
}

if (e.type === 'shot_started') {
    msgs.push({
        topic: 'homeassistant/sensor/maratui_extraction_timer/state',
        payload: '0',
        qos: 0,
        retain: false
    });
}

if (e.type === 'water_refill_needed') {
    msgs.push({
        topic: 'homeassistant/binary_sensor/maratui_water_low/state',
        payload: 'ON',
        qos: 1,
        retain: false
    });
}

if (e.type === 'water_refill_cleared') {
    msgs.push({
        topic: 'homeassistant/binary_sensor/maratui_water_low/state',
        payload: 'OFF',
        qos: 1,
        retain: false
    });
}

if (msgs.length === 0) return null;
return [msgs];
